SELECT tc.TEST_CASE_UUID, TEST_CASE_ID,TEST_CASE_NAME, TEST_SET_UUID,TEST_CASE_STATUS,TEST_CASE_EXECUTON_TYPE ,tcr.REQUIREMENT_UUID,tcr.CONDITION_SATISFACTION_UUID FROM TEST_CASE tc,TEST_CASE_REQUIREMENT tcr,REQUIREMENT req WHERE tc.TEST_CASE_UUID=tcr.TEST_CASE_UUID and tcr.REQUIREMENT_UUID=:REQUIREMENT_UUID and req.REQUIREMENT_UUID=:REQUIREMENT_UUID and tcr.CONDITION_SATISFACTION_UUID is null and req.IS_SOLO_REQUIREMENT='Yes' union SELECT tc.TEST_CASE_UUID, TEST_CASE_ID,TEST_CASE_NAME, TEST_SET_UUID,TEST_CASE_STATUS,TEST_CASE_EXECUTON_TYPE,tcr.REQUIREMENT_UUID,tcr.CONDITION_SATISFACTION_UUID FROM TEST_CASE tc,TEST_CASE_REQUIREMENT tcr,REQUIREMENT req WHERE tc.TEST_CASE_UUID=tcr.TEST_CASE_UUID and tcr.REQUIREMENT_UUID=:REQUIREMENT_UUID and req.REQUIREMENT_UUID=:REQUIREMENT_UUID or tcr.CONDITION_SATISFACTION_UUID =:CONDITION_SATISFACTION_UUID order by TEST_CASE_ID desc;